<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';require_admin();
$status=geo_status();$testResult=$_SESSION['pc_geo_test_result']??null;unset($_SESSION['pc_geo_test_result']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='auto_setup'||$action==='download'){$url='https://cdn.jsdelivr.net/npm/geolite2-city@latest/GeoLite2-City.mmdb.gz';$result=geoip_install_from_url($url);$label=$action==='auto_setup'?'Auto setup completed':'Local database updated';flash('success',$label.': GeoLite2-City installed and validated ('.number_format($result['size']/1048576,1).' MB).');}
        elseif($action==='test'){
            $ip=filter_var((string)($_POST['test_ip']??'8.8.8.8'),FILTER_VALIDATE_IP)?(string)$_POST['test_ip']:'8.8.8.8';$t=microtime(true);$result=geo_lookup($ip);$ms=round((microtime(true)-$t)*1000,3);$testResult=['ip'=>$ip,'geo'=>$result,'ms'=>$ms];$_SESSION['pc_geo_test_result']=$testResult;flash($result?'success':'error',$result?'Local GeoIP lookup succeeded in '.$ms.' ms.':'No local GeoIP record was found.');
        }elseif($action==='save_path'){
            $path=trim((string)($_POST['path']??''));if($path===''){$path='geoip/GeoLite2-City.mmdb';}if(strpos($path,'..')!==false||preg_match('~^[/\\]~',$path))throw new RuntimeException('Database path must be relative to the PocketCat project.');set_setting('geoip_city_db',str_replace('\\','/',$path));flash('success','Local GeoIP database path saved.');
        }
    }catch(Throwable $e){flash('error',$e->getMessage());}
    if($action!=='test') redirect('/admin/geo-providers/');
}
$title='Local GeoIP';require __DIR__.'/../includes/header.php';
?><div class="geo-page"><div class="page-head"><div><span class="eyebrow">SELF-HOSTED ANALYTICS</span><h1>Local GeoIP Database</h1><p>Runtime geolocation is fully local. No ipapi.co, FreeIPAPI, or geolocation API rate limits are used.</p></div></div>
<section class="stats"><div class="card stat"><span>Status</span><strong style="font-size:18px"><?= $status['available']?'Ready':($status['file_present']?'Database unreadable':'Needs database') ?></strong></div><div class="card stat"><span>Database size</span><strong><?=e($status['size_human'])?></strong></div><div class="card stat"><span>IP version</span><strong><?=e($status['ip_version']?:'—')?></strong></div><div class="card stat"><span>Record size</span><strong><?=e($status['record_size']?:'—')?> bit</strong></div></section>
<section class="card"><h2>Local database</h2><div class="metric-row"><span>Path</span><code><?=e($status['path'])?></code></div><div class="metric-row"><span>Modified</span><strong><?=e($status['modified']?:'Not installed')?></strong></div><div class="metric-row"><span>Description</span><strong><?=e($status['description']?:'GeoLite2-City')?></strong></div><p class="muted">The application reads this file directly on the server. Visitor redirects and analytics collection never make a GeoIP HTTP request.</p><?php if(!$status['available'] && $status['reader_error']): ?><div class="alert alert-error"><strong>Reader validation:</strong> <?=e($status['reader_error'])?></div><?php endif; ?></section>
<section class="card"><h2>Database path</h2><form method="post" class="grid-main"><?=csrf_field()?><input type="hidden" name="action" value="save_path"><label>Relative database path<input name="path" value="<?=e((string)setting('geoip_city_db','geoip/GeoLite2-City.mmdb'))?>"><small class="muted">Default: <code>geoip/GeoLite2-City.mmdb</code></small></label><button class="btn" type="submit">Save path</button></form></section>
<section class="card"><h2>Test local lookup</h2><form method="post" class="grid-main"><?=csrf_field()?><input type="hidden" name="action" value="test"><label>IP address<input name="test_ip" value="8.8.8.8" required></label><button class="btn" type="submit">Lookup locally</button></form><?php if($testResult):?><div class="card" style="margin-top:16px"><strong><?=e($testResult['ip'])?></strong><span class="muted"> · <?=e((string)$testResult['ms'])?> ms</span><pre><?=e(json_encode($testResult['geo'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></div><?php endif;?></section>
<section class="card"><h2>Automatic setup</h2><p>Use Auto Setup when the database is missing or unreadable. PocketCat downloads the current GeoLite2-City distribution, installs it locally, validates the MaxMind database, and leaves runtime lookups fully local.</p><form method="post" style="margin-bottom:12px"><?=csrf_field()?><input type="hidden" name="action" value="auto_setup"><button class="btn" type="submit">Auto Setup / Repair Local GeoIP</button></form><h3>Install / update</h3><p class="muted">For a manual refresh, PocketCat can download the current packaged GeoLite2-City distribution. Visitor tracking never calls the download source.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="download"><button class="btn" type="submit">Install / Update Local GeoLite2</button></form><p class="muted">For controlled production environments, use your MaxMind account/license with <code>php geoip/update.php</code> instead.</p></section>
